/*
 * A228268  Primes n of the form 1000p+q with primes p and q, 998>p>q>100.
 * https://oeis.org/A228268
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  fini, full, nonn
 * Formula:   a(n) = the nth prime of the form 1000·p + q, where p and q are
 *            primes, 998 > p > q > 100. The sequence is generated by
 *            enumerating all pairs (p, q), forming the candidate, testing
 *            primality, collecting all results, sorting them, and caching the
 *            sorted list
 * Range:     u8 none, u16 none, u32 n <= 1346, u64 n <= 1346, u128 n <= 1346,
 *            big any n
 * Helpers:   is_prime_small, seq_cmp, sieve_primes
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>

#include "../utils/sieve_primes.h"
#include "../utils/is_prime_small.h"
#include "../utils/seq_cmp.h"

/* Append `val` to the dynamic array `arr`, reallocating when necessary. */
static void append_value(seq_t **arr, size_t *len, size_t *cap, seq_t val)
{
    if (*len + 1 > *cap) {
        size_t new_cap = (*cap == 0) ? 64 : (*cap << 1);
        seq_t *tmp = (seq_t *)realloc(*arr, new_cap * sizeof(seq_t));
        if (!tmp) abort();
        *arr = tmp;
        *cap = new_cap;
    }
    (*arr)[(*len)++] = val;
}

/* Return the *n*th element of the sequence (1‑based).  If *n* is out of
   range, 0 is returned.  The complete sequence is built and cached on
   the first call. */
seq_t a(idx_t n)
{
    /* Static cache of the entire sequence. */
    static seq_t  *cache    = NULL;
    static size_t cache_len = 0;
    static size_t cache_cap = 0;

    if (!cache_cap) { /* first call: build the entire sequence */
        /* Obtain all primes up to 997 (all 3‑digit primes). */
        idx_t *primes3 = NULL;
        size_t primes_cnt = 0;
        sieve_primes(997, &primes3, &primes_cnt);

        /* Enumerate all valid pairs (p, q) and collect prime candidates. */
        for (size_t i = 0; i < primes_cnt; ++i) {
            uint64_t p = (uint64_t)primes3[i];
            if (p <= 100 || p >= 998) continue;  /* 998 > p > 100 */

            for (size_t j = 0; j < i; ++j) {          /* q < p */
                uint64_t q = (uint64_t)primes3[j];
                if (q <= 100) continue;               /* q > 100 */

                seq_t cand = (seq_t)(p * 1000ULL + q);
                if (is_prime_small(cand))
                    append_value(&cache, &cache_len, &cache_cap, cand);
            }
        }

        free(primes3);   /* free temporary prime list */

        /* Sort the candidates in ascending order. */
        qsort(cache, cache_len, sizeof(seq_t), seq_cmp);
    }

    if (n == 0 || (idx_t)n > cache_len) return (seq_t)0;
    return cache[(size_t)(n - 1)];
}
